<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeCustomCssVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Holder\ThemeCustomCssAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ThemeCustomCssAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class ThemeCustomCssAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getCustomCss returns null on a freshly created holder.
         */
        public function testCustomCssNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithThemeCustomCssAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isCustomCssAssigned());
            $this->assertNull($holder->getCustomCss());
        }
}
class ImplWithThemeCustomCssAttributeHolderUnitTest
{
  use ThemeCustomCssAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedCustomCssRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultCustomCss();
    }}
